import * as THREE from 'three';
import RAPIER from '@dimforge/rapier3d-compat';
import type { Vec3 } from '../contracts/math';
import type { DoorObstacle as DoorObstacleDescriptor } from '../courses/types';

export type DoorState = 'closed' | 'opening' | 'open' | 'closing';

export class DoorObstacle {
  readonly id: string;
  readonly group: THREE.Group;
  readonly collider: RAPIER.Collider;
  readonly body: RAPIER.RigidBody;
  
  state: DoorState;
  progress: number;
  private readonly openDuration: number;
  private readonly size: Vec3;
  private readonly hingeOffset: number;

  constructor(
    world: RAPIER.World,
    descriptor: DoorObstacleDescriptor,
  ) {
    this.id = descriptor.id;
    this.size = descriptor.size;
    this.openDuration = descriptor.openDuration ?? 1.0;
    this.state = descriptor.initialState === 'open' ? 'open' : 'closed';
    this.progress = this.state === 'open' ? 1 : 0;

    this.group = new THREE.Group();
    this.group.position.set(descriptor.transform.position.x, descriptor.transform.position.y, descriptor.transform.position.z);
    if (descriptor.transform.rotation) {
      this.group.quaternion.set(descriptor.transform.rotation.x, descriptor.transform.rotation.y, descriptor.transform.rotation.z, descriptor.transform.rotation.w);
    }

    this.hingeOffset = this.size.x / 2;

    const geometry = new THREE.BoxGeometry(this.size.x, this.size.y, this.size.z);
    const material = new THREE.MeshStandardMaterial({ color: 0x8B4513 });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.x = this.hingeOffset;
    this.group.add(mesh);

    const bodyDesc = RAPIER.RigidBodyDesc.kinematicPositionBased()
      .setTranslation(
        descriptor.transform.position.x,
        descriptor.transform.position.y,
        descriptor.transform.position.z
      );
    this.body = world.createRigidBody(bodyDesc);

    const colliderDesc = RAPIER.ColliderDesc.cuboid(this.size.x / 2, this.size.y / 2, this.size.z / 2)
      .setTranslation(this.hingeOffset, 0, 0);
    this.collider = world.createCollider(colliderDesc, this.body);
  }

  open(): void {
    if (this.state === 'closed' || this.state === 'closing') {
      this.state = 'opening';
    }
  }

  close(): void {
    if (this.state === 'open' || this.state === 'opening') {
      this.state = 'closing';
    }
  }

  update(dt: number): void {
    if (this.state === 'opening') {
      this.progress += dt / this.openDuration;
      if (this.progress >= 1) {
        this.progress = 1;
        this.state = 'open';
      }
    } else if (this.state === 'closing') {
      this.progress -= dt / this.openDuration;
      if (this.progress <= 0) {
        this.progress = 0;
        this.state = 'closed';
      }
    }

    const angle = this.progress * (Math.PI / 2);
    this.group.rotation.y = angle;
    
    const q = new THREE.Quaternion();
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), angle);
    
    this.body.setNextKinematicRotation({ x: q.x, y: q.y, z: q.z, w: q.w });
  }

  dispose(world: RAPIER.World): void {
    world.removeRigidBody(this.body);
    this.group.clear();
  }
}
